#!/usr/bin/env bash
# Tests for scripts/gen-cuda12.sh and the committed
# onnxruntime-split-cuda12/PKGBUILD: --check passes on the tree; the
# committed file differs from onnxruntime-split/PKGBUILD in the stamped
# lines only; on a copy of the script and the recipes (under mktemp) a run
# on an up-to-date file is a no-op, an altered or missing generated file
# fails --check (exit 1, with a diff) and a run mends it, and a source that
# lacks a stamped line, or has one twice, fails (exit 2) and writes
# nothing; usage errors exit 2; git neither ignores the file nor would the
# licence guard refuse it.
# Usage: scripts/tests/gen-cuda12-test.sh. Exits non-zero on any failure.
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
top=$(cd "$here/../.." && pwd)
src=$top/onnxruntime-split/PKGBUILD
gen=$top/onnxruntime-split-cuda12/PKGBUILD

fails=0 count=0
ok() { count=$((count + 1)); echo "ok   $1"; }
fail() { count=$((count + 1)); echo "FAIL $1"; fails=$((fails + 1)); }

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

echo "== the tree"
if out=$("$top/scripts/gen-cuda12.sh" --check 2>&1); then ok "--check passes on the tree"; else
    fail "--check on the tree: $out"; fi
# The stamped lines, and nothing else (diff's own lines, <source >generated).
want=$(
    cat <<'EOF'
> # Generated by scripts/gen-cuda12.sh from onnxruntime-split/PKGBUILD
> # (https://github.com/rsd/omarchy-onnxruntime): do not edit; change the
> # source and regenerate.
> #
< pkgbase=onnxruntime-split
> pkgbase=onnxruntime-split-cuda12
< _ortf_default_eps='cuda tensorrt openvino'
< _ortf_default_cuda_archs=rtx
< _ortf_default_python=1
> _ortf_default_eps='cuda'
> _ortf_default_cuda_archs=legacy
> _ortf_default_python=0
< _ortf_line=main
> _ortf_line=cuda12
< _ortf_cuda_major_default=13
> _ortf_cuda_major_default=12
EOF
)
got=$(diff "$src" "$gen" | grep '^[<>]' | grep -v -e '^< pkgrel=' -e '^> pkgrel=' \
    -e "^> # onnxruntime-split-cuda12's own pkgrel" -e "^> # notes above are those of onnxruntime-split's." || true)
if [[ $got == "$want" ]]; then ok "the generated file differs from the source in the stamped lines only"; else
    fail "the differences: $(diff <(echo "$want") <(echo "$got"))"; fi
if grep -qxF 'pkgrel=1' "$gen" && (($(grep -c '^pkgrel=' "$gen") == 1)) &&
    grep -qxF "# onnxruntime-split-cuda12's own pkgrel (scripts/gen-cuda12.sh); the" "$gen"; then
    ok "its own pkgrel, 1, with a comment saying so"
else
    fail "the pkgrel lines: $(grep -n 'pkgrel=' "$gen")"
fi
if [[ $(sed -n 1p "$gen") == "$(sed -n 1p "$src")" && $(sed -n 3p "$gen") == '# Generated by scripts/gen-cuda12.sh from onnxruntime-split/PKGBUILD' ]]; then
    ok "the Maintainer line first, then the generated-file notice"
else
    fail "the top of the generated file: $(head -n 4 "$gen")"
fi
if git -C "$top" check-ignore -q onnxruntime-split-cuda12/PKGBUILD; then
    fail "git ignores onnxruntime-split-cuda12/PKGBUILD"
else
    ok "git does not ignore onnxruntime-split-cuda12/PKGBUILD"
fi
for f in src/x pkg/x onnxruntime/x ortf-dep-onnx.zip; do
    if git -C "$top" check-ignore -q "onnxruntime-split-cuda12/$f"; then ok "git ignores onnxruntime-split-cuda12/$f"; else
        fail "git does not ignore onnxruntime-split-cuda12/$f (makepkg's work files)"; fi
done
if ! grep -qiE "$(sed -n "s/^    -e '\(copyright[^']*\)'.*/\1/p" "$top/scripts/check-no-vendor.sh" | paste -sd '|')" "$gen" &&
    ! LC_ALL=C grep -q '[^[:print:][:space:]]' "$gen" && (($(wc -c <"$gen") < 1048576)); then
    ok "the generated PKGBUILD is small plain text without a vendor copyright line"
else
    fail "the generated PKGBUILD would trip the licence guard"
fi

echo "== a copy of the script and the recipes"
copy=$tmp/repo
mkdir -p "$copy/scripts" "$copy/onnxruntime-split" "$copy/onnxruntime-split-cuda12"
cp "$top/scripts/gen-cuda12.sh" "$copy/scripts/"
cp "$src" "$copy/onnxruntime-split/"
cp "$gen" "$copy/onnxruntime-split-cuda12/"
cgen=$copy/onnxruntime-split-cuda12/PKGBUILD
if "$copy/scripts/gen-cuda12.sh" --check >/dev/null 2>&1; then ok "the copy checks out"; else
    fail "the unaltered copy fails --check"; fi
touch -d '2000-01-01 00:00' "$cgen"
before=$(stat -c %Y "$cgen")
if out=$("$copy/scripts/gen-cuda12.sh" 2>&1) && grep -qF 'is up to date' <<<"$out" &&
    [[ $(stat -c %Y "$cgen") == "$before" ]] && cmp -s "$cgen" "$gen"; then
    ok "a run on an up-to-date file leaves it untouched"
else
    fail "a second run: $out"
fi
sed -i 's/^pkgrel=1$/pkgrel=2/' "$cgen"
status=0
out=$("$copy/scripts/gen-cuda12.sh" --check 2>&1) || status=$?
if ((status == 1)) && grep -qxF -- '-pkgrel=2' <<<"$out" && grep -qxF -- '+pkgrel=1' <<<"$out" &&
    grep -qF 'onnxruntime-split-cuda12/PKGBUILD is stale: run gen-cuda12.sh' <<<"$out"; then
    ok "an altered generated file fails --check (exit 1) with a diff"
else
    fail "an altered generated file (exit $status): $out"
fi
if "$copy/scripts/gen-cuda12.sh" >/dev/null && "$copy/scripts/gen-cuda12.sh" --check >/dev/null && cmp -s "$cgen" "$gen"; then
    ok "a run mends it, to the committed one"
else
    fail "a run did not restore the generated file"
fi
# A change to the source reaches the generated file only through a run.
sed -i 's/^pkgver=1.29.0$/pkgver=1.29.1/' "$copy/onnxruntime-split/PKGBUILD"
status=0
out=$("$copy/scripts/gen-cuda12.sh" --check 2>&1) || status=$?
if ((status == 1)) && grep -qxF -- '+pkgver=1.29.1' <<<"$out"; then ok "a changed source makes the generated file stale"; else
    fail "a changed source (exit $status): $out"; fi
"$copy/scripts/gen-cuda12.sh" >/dev/null
if grep -qxF 'pkgver=1.29.1' "$cgen" && grep -qxF 'pkgbase=onnxruntime-split-cuda12' "$cgen"; then
    ok "and a run carries it over, stamped"
else
    fail "the regenerated file: $(grep -n '^pkg' "$cgen")"
fi
rm "$cgen"
status=0
out=$("$copy/scripts/gen-cuda12.sh" --check 2>&1) || status=$?
if ((status == 1)) && grep -qF 'does not exist' <<<"$out"; then ok "a missing generated file fails --check"; else
    fail "a missing generated file (exit $status): $out"; fi
rm -r "$copy/onnxruntime-split-cuda12"
if "$copy/scripts/gen-cuda12.sh" >/dev/null && [[ -f $cgen ]]; then ok "a run creates the directory and the file"; else
    fail "a run without onnxruntime-split-cuda12/"; fi

echo "== a source that drifted"
# Each stamped line removed, then doubled: the generator fails and leaves
# the generated file as it was.
cp "$src" "$copy/onnxruntime-split/PKGBUILD"
"$copy/scripts/gen-cuda12.sh" >/dev/null
for name in pkgbase _ortf_default_eps _ortf_default_cuda_archs _ortf_default_python _ortf_line \
    _ortf_cuda_major_default pkgrel; do
    line=$(grep -m1 "^$name=" "$src")
    for how in removed doubled; do
        if [[ $how == removed ]]; then
            grep -v "^$name=" "$src" >"$copy/onnxruntime-split/PKGBUILD"
            n=0
        else
            sed "/^$name=/p" "$src" >"$copy/onnxruntime-split/PKGBUILD"
            n=2
        fi
        status=0
        out=$("$copy/scripts/gen-cuda12.sh" 2>&1) || status=$?
        if ((status == 2)) && grep -qF "has $n lines $name=..., not exactly one" <<<"$out" && cmp -s "$cgen" "$gen"; then
            ok "$line $how: fails (exit 2), writes nothing"
        else
            fail "$line $how (exit $status): $out"
        fi
    done
done
grep -v '^# Maintainer: ' "$src" >"$copy/onnxruntime-split/PKGBUILD"
status=0
out=$("$copy/scripts/gen-cuda12.sh" --check 2>&1) || status=$?
if ((status == 2)) && grep -qF "0 '# Maintainer: ' lines" <<<"$out"; then ok "no Maintainer line: fails (exit 2)"; else
    fail "no Maintainer line (exit $status): $out"; fi
cp "$src" "$copy/onnxruntime-split/PKGBUILD"
# An indented line of the same name (a function's) is not a stamped line.
printf 'f() {\n  pkgrel=9\n}\n' >>"$copy/onnxruntime-split/PKGBUILD"
if "$copy/scripts/gen-cuda12.sh" >/dev/null 2>&1 && grep -qxF '  pkgrel=9' "$cgen"; then
    ok "an indented name=... line is left alone"
else
    fail "an indented pkgrel= line"
fi

echo "== usage"
for args in '--bogus' '--check extra' '--write'; do
    status=0
    # shellcheck disable=SC2086 # the arguments are words
    "$copy/scripts/gen-cuda12.sh" $args >/dev/null 2>&1 || status=$?
    if ((status == 2)); then ok "usage error for [$args]"; else fail "[$args] exits $status, not 2"; fi
done

if ((fails > 0)); then
    echo "$fails of $count check(s) failed"
    exit 1
fi
echo "all $count checks passed"
